export const EMBEDDED_FLOW_CAPABILITIES_YAML: string = "# Toxic-flow capability patterns (docs/toxic-flow.md).\n#\n# Which tool calls contribute each session capability: private data access,\n# untrusted content exposure and external communication. These are not\n# single-call threat rules (they never block a call on their own), so they live\n# under threats/flow/ and are not counted with the threats/*.yaml rule files.\n#\n# Loaded by packages/core/src/toxic-flow-capabilities.ts. Connectors read this\n# file from their bundled threats directory; the core also embeds a byte-for-byte\n# copy (toxic-flow-capabilities.data.ts, regenerated by\n# `node packages/core/scripts/embed-flow-capabilities.mjs`) that is used when a\n# threats directory has no flow/capabilities.yaml, for example the MCP gateway's\n# embedded rule set. A drift test fails when the two differ.\n#\n# Patterns are JavaScript regular expressions. `flags` accepts i, m, s and u.\n# An invalid file is rejected as a whole and the embedded copy is used instead.\n\nschema_version: 1\n\n# Package registries, language docs and source hosts. A plain request to one of\n# them is not external communication; a request that carries a payload still is.\n# Extended per install by `toxic_flow.trusted_domains`.\ntrusted_domains:\n  - 'registry.npmjs.org'\n  - 'npmjs.com'\n  - 'registry.yarnpkg.com'\n  - 'yarnpkg.com'\n  - 'pypi.org'\n  - 'files.pythonhosted.org'\n  - 'pythonhosted.org'\n  - 'crates.io'\n  - 'docs.rs'\n  - 'rust-lang.org'\n  - 'proxy.golang.org'\n  - 'sum.golang.org'\n  - 'pkg.go.dev'\n  - 'go.dev'\n  - 'golang.org'\n  - 'rubygems.org'\n  - 'repo.maven.apache.org'\n  - 'repo1.maven.org'\n  - 'plugins.gradle.org'\n  - 'services.gradle.org'\n  - 'nuget.org'\n  - 'packagist.org'\n  - 'jsr.io'\n  - 'deno.land'\n  - 'nodejs.org'\n  - 'python.org'\n  - 'developer.mozilla.org'\n  - 'conda.anaconda.org'\n  - 'repo.anaconda.com'\n  - 'deb.debian.org'\n  - 'archive.ubuntu.com'\n  - 'security.ubuntu.com'\n  - 'dl-cdn.alpinelinux.org'\n  - 'registry-1.docker.io'\n  - 'registry.hub.docker.com'\n  - 'ghcr.io'\n  - 'github.com'\n  - 'codeload.github.com'\n  - 'objects.githubusercontent.com'\n  - 'gitlab.com'\n  - 'bitbucket.org'\n\n# Paste, file-drop, request-capture and chat-webhook services. An egress to one\n# of these is always external communication that carries data. An entry with a\n# path (`discord.com/api/webhooks`) also requires that path in the URL.\nexfil_sinks:\n  - 'pastebin.com'\n  - 'paste.ee'\n  - 'pastes.io'\n  - 'paste.rs'\n  - 'paste.debian.net'\n  - 'hastebin.com'\n  - 'hastebin.skyra.pw'\n  - 'ghostbin.co'\n  - 'dpaste.org'\n  - 'dpaste.com'\n  - 'bpa.st'\n  - 'ix.io'\n  - 'sprunge.us'\n  - 'termbin.com'\n  - '0x0.st'\n  - 'transfer.sh'\n  - 'file.io'\n  - 'tmpfiles.org'\n  - 'catbox.moe'\n  - 'gofile.io'\n  - 'anonfiles.com'\n  - 'rentry.co'\n  - 'privatebin.net'\n  - 'justpaste.it'\n  - 'controlc.com'\n  - 'gist.github.com'\n  - 'gist.githubusercontent.com'\n  - 'webhook.site'\n  - 'requestbin.net'\n  - 'requestcatcher.com'\n  - 'pipedream.net'\n  - 'beeceptor.com'\n  - 'hookbin.com'\n  - 'ngrok.io'\n  - 'ngrok-free.app'\n  - 'ngrok.app'\n  - 'trycloudflare.com'\n  - 'interact.sh'\n  - 'oast.fun'\n  - 'oast.pro'\n  - 'oast.live'\n  - 'oast.site'\n  - 'oast.online'\n  - 'oast.me'\n  - 'burpcollaborator.net'\n  - 'hooks.slack.com'\n  - 'api.telegram.org'\n  - 'discord.com/api/webhooks'\n  - 'discordapp.com/api/webhooks'\n\n# Credential stores, key material and data dumps, matched against a normalized\n# path (home spellings collapsed to `~`, backslashes to `/`). The first match wins.\n# kind: sensitive_file | database_dump. secret: credential-grade material.\nsensitive_paths:\n  - label: 'SSH private key'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])\\.ssh[\\\\/](?:id_[a-z0-9_-]+|identity)(?!\\.pub)$'\n    flags: i\n  - label: 'cloud credentials'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])\\.aws[\\\\/](?:credentials|config|sso[\\\\/]cache[\\\\/].+)$'\n    flags: i\n  - label: 'cloud credentials'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])\\.config[\\\\/]gcloud[\\\\/].*(?:credential|token|\\.json$|\\.db$)'\n    flags: i\n  - label: 'cloud credentials'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])\\.azure[\\\\/](?:accessTokens\\.json|msal_token_cache.*|azureProfile\\.json)$'\n    flags: i\n  - label: 'environment secrets file'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])\\.env(?:\\.(?!example$|sample$|template$|dist$|defaults?$)[\\w-]{1,40})?$'\n    flags: i\n  - label: 'credential file'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])\\.(?:netrc|pgpass|npmrc|pypirc|git-credentials|my\\.cnf|vault-token|boto)$'\n    flags: i\n  - label: 'registry credentials'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])\\.docker[\\\\/]config\\.json$'\n    flags: i\n  - label: 'cluster credentials'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:(?:^|[\\\\/])\\.kube[\\\\/]config|(?:^|[\\\\/])kubeconfig(?:\\.ya?ml)?)$'\n    flags: i\n  - label: 'GitHub CLI token'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])\\.config[\\\\/]gh[\\\\/]hosts\\.ya?ml$'\n    flags: i\n  - label: 'private keyring'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])\\.gnupg[\\\\/](?:private-keys-v1\\.d|secring\\.gpg)'\n    flags: i\n  - label: 'key material'\n    kind: sensitive_file\n    secret: true\n    pattern: '\\.(?:pem|key|p12|pfx|jks|keystore|ppk|kdbx|ovpn)$'\n    flags: i\n  - label: 'credential file'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])(?:credentials|secrets?|service[-_]?account(?:[-_][\\w-]{0,40})?)\\.(?:json|ya?ml|toml|ini|txt)$'\n    flags: i\n  - label: 'secret store'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])(?:master\\.key|credentials\\.yml\\.enc|terraform\\.tfstate(?:\\.backup)?)$'\n    flags: i\n  - label: 'system password store'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])etc[\\\\/](?:shadow|gshadow|sudoers|master\\.passwd)$'\n    flags: i\n  - label: 'browser credential store'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])(?:Login Data|Cookies|Local State|key[34]\\.db|logins\\.json|cookies\\.sqlite)$'\n    flags: i\n  - label: 'OS keychain'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:^|[\\\\/])(?:Library[\\\\/]Keychains|\\.local[\\\\/]share[\\\\/]keyrings)(?:[\\\\/]|$)'\n    flags: i\n  - label: 'crypto wallet'\n    kind: sensitive_file\n    secret: true\n    pattern: '(?:(?:^|[\\\\/])wallet\\.dat|(?:^|[\\\\/])\\.(?:bitcoin|ethereum)[\\\\/]keystore)'\n    flags: i\n  - label: 'shell history'\n    kind: sensitive_file\n    secret: false\n    pattern: '(?:^|[\\\\/])\\.(?:bash|zsh|sh|psql|mysql|python)_history$'\n    flags: i\n  - label: 'database dump'\n    kind: database_dump\n    secret: true\n    pattern: '(?:^|[\\\\/])[^\\\\/]*(?:dump|backup)[^\\\\/]*\\.(?:sql|dump|bak|gz|tar|zip)$|\\.dump$'\n    flags: i\n\n# Commands that print credentials or dump a database (matched on the command text).\n# kind: credential_command | database_dump.\ncredential_commands:\n  - label: 'environment dump'\n    kind: credential_command\n    pattern: '(?:^|[;&|(]\\s*)(?:printenv|env|set)\\s*(?:$|[;&|>)])'\n  - label: 'process environment'\n    kind: credential_command\n    pattern: '\\/proc\\/(?:self|\\d+)\\/environ\\b'\n  - label: 'keychain read'\n    kind: credential_command\n    pattern: '\\bsecurity\\s+(?:find-(?:generic|internet)-password|dump-keychain)\\b'\n  - label: 'private key export'\n    kind: credential_command\n    pattern: '\\bgpg2?\\b[^\\n]{0,200}--export-secret-(?:sub)?keys\\b'\n  - label: 'cloud secret read'\n    kind: credential_command\n    pattern: '\\baws\\s+(?:configure\\s+(?:get|export-credentials)|sts\\s+get-session-token|secretsmanager\\s+get-secret-value|ssm\\s+get-parameters?\\b[^\\n]{0,200}--with-decryption)'\n  - label: 'cloud token read'\n    kind: credential_command\n    pattern: '\\bgcloud\\s+auth\\s+(?:application-default\\s+)?print-(?:access|identity)-token\\b'\n  - label: 'cloud token read'\n    kind: credential_command\n    pattern: '\\baz\\s+account\\s+get-access-token\\b'\n  - label: 'GitHub token read'\n    kind: credential_command\n    pattern: '\\bgh\\s+auth\\s+(?:token|status\\s+[^\\n]{0,40}--show-token)\\b'\n  - label: 'git credential read'\n    kind: credential_command\n    pattern: '\\bgit\\s+credential\\s+fill\\b'\n  - label: 'cluster secret read'\n    kind: credential_command\n    pattern: '\\bkubectl\\s+get\\s+secrets?\\b'\n  - label: 'vault secret read'\n    kind: credential_command\n    pattern: '\\bvault\\s+(?:kv\\s+get|read)\\b'\n  - label: 'password manager read'\n    kind: credential_command\n    pattern: '\\bop\\s+(?:read|item\\s+get)\\b'\n  - label: 'database dump'\n    kind: database_dump\n    pattern: '\\b(?:pg_dump|pg_dumpall|mysqldump|mariadb-dump|mongodump|mongoexport)\\b|\\bsqlite3\\b[^\\n]{0,200}\\.dump\\b'\n\n# Destructive commands for the injection_to_action chain. `rm -r` of a broad\n# target is matched separately (broad_delete_targets / broad_delete_patterns).\ndestructive_commands:\n  - label: 'git force push'\n    pattern: '\\bgit\\s+(?:-[Cc]\\s+\\S+\\s+)*push\\b[^\\n;&|]{0,300}?(?:\\s--force(?:-with-lease)?\\b|\\s-f\\b|\\s--mirror\\b|\\s\\+\\S)'\n  - label: 'git reset --hard'\n    pattern: '\\bgit\\s+reset\\s+[^\\n;&|]{0,100}--hard\\b'\n  - label: 'git clean -f'\n    pattern: '\\bgit\\s+clean\\s+-[a-zA-Z]*f'\n  - label: 'find -delete'\n    pattern: '\\bfind\\b[^\\n;&|]{0,300}\\s(?:-delete\\b|-exec\\s+rm\\b)'\n  - label: 'disk/file wipe'\n    pattern: '\\b(?:mkfs(?:\\.\\w+)?|wipefs|shred)\\b'\n  - label: 'raw device write'\n    pattern: '\\bdd\\b[^\\n;&|]{0,200}\\bof=\\/dev\\/'\n  - label: 'recursive permission change on home or root'\n    pattern: '\\bch(?:mod|own)\\s+-R\\b[^\\n;&|]{0,200}\\s(?:\\/|~|\\$HOME|\\$\\{HOME\\})(?:\\s|$)'\n  - label: 'SQL drop/truncate'\n    pattern: '\\b(?:drop\\s+(?:table|database|schema)|truncate\\s+table)\\b'\n    flags: i\n  - label: 'SQL delete without WHERE'\n    pattern: '\\bdelete\\s+from\\s+[\\w.\"`]+\\s*(?:;|$|[\"''])'\n    flags: i\n  - label: 'terraform destroy'\n    pattern: '\\bterraform\\s+(?:destroy\\b|apply\\b[^\\n;&|]{0,200}-destroy\\b)'\n  - label: 'pulumi destroy'\n    pattern: '\\bpulumi\\s+destroy\\b'\n  - label: 'kubectl delete'\n    pattern: '\\bkubectl\\s+delete\\b'\n  - label: 'helm uninstall'\n    pattern: '\\bhelm\\s+(?:uninstall|delete)\\b'\n  - label: 'S3 recursive delete'\n    pattern: '\\baws\\s+s3\\s+(?:rm\\b[^\\n;&|]{0,300}--recursive|rb\\b)'\n  - label: 'bucket recursive delete'\n    pattern: '\\bgsutil\\s+(?:-m\\s+)?rm\\s+-r\\b'\n  - label: 'docker prune'\n    pattern: '\\bdocker\\s+(?:system\\s+prune\\b|volume\\s+(?:rm|prune)\\b)'\n  - label: 'crontab removal'\n    pattern: '\\bcrontab\\s+-r\\b'\n  - label: 'recursive delete'\n    pattern: '\\bRemove-Item\\b[^\\n;&|]{0,300}-Recurse\\b'\n    flags: i\n  - label: 'recursive delete'\n    pattern: '\\b(?:rd|rmdir)\\s+\\/s\\b'\n    flags: i\n\n# `rm -r` targets that count as a broad delete (exact match, quotes stripped).\nbroad_delete_targets:\n  - '/'\n  - '/*'\n  - '~'\n  - '~/'\n  - '~/*'\n  - '$HOME'\n  - '${HOME}'\n  - '$HOME/'\n  - '$HOME/*'\n  - '*'\n  - '.'\n  - './'\n  - './*'\n  - '..'\n  - '../'\n  - '.*'\n  - '.git'\n  - './.git'\nbroad_delete_patterns:\n  - '^\\/[^/]+\\/?\\*?$'\n  - '^\\/(?:home|Users)\\/[^/]+\\/?\\*?$'\n  - '^(?:~|\\$HOME|\\$\\{HOME\\})\\/[^/]+\\/?\\*?$'\n  - '^[A-Za-z]:[\\\\/]?$'\n\n# Words skipped before the executable of a shell stage (`sudo`, `env A=B`, `timeout 5`).\ncommand_prefixes:\n  - 'sudo'\n  - 'doas'\n  - 'command'\n  - 'exec'\n  - 'time'\n  - 'nohup'\n  - 'nice'\n  - 'ionice'\n  - 'stdbuf'\n  - 'timeout'\n  - 'env'\n  - 'builtin'\n\n# Executables by role, matched on the lower-cased basename (`.exe` stripped).\nexecutables:\n  http_clients:\n    - 'curl'\n    - 'wget'\n    - 'http'\n    - 'https'\n    - 'xh'\n    - 'xhs'\n    - 'httpie'\n    - 'aria2c'\n    - 'invoke-webrequest'\n    - 'iwr'\n    - 'invoke-restmethod'\n    - 'irm'\n    - 'lwp-request'\n    - 'fetch'\n  raw_socket_clients:\n    - 'nc'\n    - 'ncat'\n    - 'netcat'\n    - 'socat'\n    - 'telnet'\n  copy_clients:\n    - 'scp'\n    - 'rsync'\n    - 'sftp'\n  mail_clients:\n    - 'sendmail'\n    - 'mail'\n    - 'mailx'\n    - 'mutt'\n    - 'swaks'\n    - 'msmtp'\n    - 's-nail'\n  dns_clients:\n    - 'dig'\n    - 'nslookup'\n    - 'host'\n    - 'drill'\n  interpreters:\n    - 'python'\n    - 'python3'\n    - 'python2'\n    - 'node'\n    - 'nodejs'\n    - 'ruby'\n    - 'perl'\n    - 'php'\n    - 'deno'\n    - 'bun'\n  shells:\n    - 'sh'\n    - 'bash'\n    - 'zsh'\n    - 'dash'\n    - 'ksh'\n    - 'fish'\n\n# Interpreter one-liners (`python -c`, `node -e`): code that uses a network API,\n# and the hint that it sends a payload rather than only fetching.\ninterpreter_network_api:\n  pattern: '(?:requests\\.|urllib|http\\.client|urlopen|fetch\\(|axios|XMLHttpRequest|net\\.connect|socket\\.|Net::HTTP|LWP|HTTP::Tiny|curl_exec|file_get_contents\\(\\s*[''\"]https?)'\ninterpreter_payload_hint:\n  pattern: '(?:post|put|patch|body|data=|json=|send|write|sendall)'\n  flags: i\n\n# Tool-name patterns, matched on the tool name (for MCP tools, the tool part of\n# `mcp__<server>__<tool>`).\ntool_names:\n  # Tools that send data out (messages, issues, uploads, webhooks).\n  send:\n    pattern: '(?:^|[_\\-.])(?:send|post|publish|upload|e?mail|message|notify|tweet|webhook|share|reply|comment|dm|chat_?post|create_(?:issue|comment|gist|pull_request|pr|message|post|note|page|message))(?:$|[_\\-.])'\n    flags: i\n  # Browser, scraper and fetch tools: their output is untrusted web content.\n  web_read:\n    pattern: '(?:browser|browse|navigate|playwright|puppeteer|scrape|crawl|firecrawl|web_?search|search_?web|web_?fetch|fetch_?url|http_?get|read_?url|open_?url|google_?search|brave_?search|tavily|exa_?search)'\n    flags: i\n  # Search tools (the whole tool name).\n  web_search:\n    pattern: '^(?:web_?search|search_?web|google_?search|brave_?search|tavily_?search|exa_?search)$'\n    flags: i\n  # Tools that read a file; writes are not reads.\n  file_read:\n    pattern: '(?:^|_)(?:read|get|cat|view|open|download|load|show|head|tail)(?:_|$)'\n    flags: i\n";
